export function findById(id) { return SLOTS.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return SLOTS.slice();
  return SLOTS.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return SLOTS.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return SLOTS.filter(x => x.enabled !== false); }
export const COUNT = SLOTS.length;
